"""Complete remaining fish mayonnaise recipes and consolidate matching sources."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g commercially pasteurized liquid egg yolk per yolk; do not substitute unpasteurized raw egg.')
def mustard(a):return I('mustard',a,'tsp','dry mustard powder','Use the same volume of prepared Dijon mustard for a milder flavor.')
def cayenne():return I('cayenne',.0625,'tsp','ground cayenne pepper','Omit for a mild mayonnaise.')
def lemon(a):return I('lemon',a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
COLD='Transfer to a clean covered container and refrigerate immediately at 4°C (40°F) or colder. Use within 3 days, using a clean spoon each time. This is fresh homemade mayonnaise, not a shelf-stable preserve.'
def emulsion(keys):
 return ['Set a clean small bowl on a damp towel to steady it. Whisk '+', '.join(tk(k) for k in keys)+' until smooth.','Measure {{oil}} into a jug. Whisk continuously while adding it drop by drop at first. Once the mixture is thick and glossy, add the remaining measured oil in a very thin stream, whisking until fully incorporated. Stop pouring if oil pools on the surface and whisk until it blends in.','The finished mayonnaise should be smooth and creamy. If it separates, put 1 teaspoon cold drinking water in a clean bowl and whisk the separated mixture into it a few drops at a time; this small repair addition changes the yield slightly.',COLD]
def eggsource(r):r['source']+=' Raw-yolk handling uses commercially pasteurized egg: https://www.foodsafety.gov/people-at-risk .';return r
def eggs(a):return I('eggs',a,'','large eggs for hard boiling','Use large pasteurized shell eggs if preferred; cook until the yolks are firm.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water, topping up to cover as directed.')
def boil():return ['Put {{eggs}} in a saucepan with {{water}}, adding more water only if needed to cover by about 2 cm. Bring to a boil, cover, remove from heat and stand for 12 minutes. Cool under cold running water, peel and cut open; the yolks must be firm throughout.']
END='Keep covered at 4°C (40°F) or colder until serving. Refrigerate leftovers within 2 hours and use within 2 days. Do not leave the platter at room temperature for more than 2 hours.'
REF=' Cooking endpoints: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures . Variety meats: https://ask.fsis.usda.gov/article/What-are-the-recommended-cooking-times-for-veal .'
def finish(r):r['category']='Main dishes';r['source']+=REF;return eggsource(r)

merges=[];updatedids=[]
def merge(n,r,reason):
 s=src(n);aliases[s['id']]=dict(id=s['id'],canonicalId=r['id'],bodySha256=s['bodySha256'],reason=reason)
 if s['id'] not in r['sourceAliases']:r['sourceAliases'].append(s['id']);r['source']+=' Equivalent source retained: '+s['recipe']['source']
 records.pop(s['id'],None);merges.append(s)

DAY='Cover and refrigerate promptly at 4°C (40°F) or colder. Use within 1 day, keep cold until serving, and refrigerate within 2 hours of preparation.'
FISHREF=' Cooking endpoints: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures .'
def fishdone(r):r['category']='Main dishes';r['source']+=FISHREF;return eggsource(r)
def roeitems():return [I('roe',15,'g','raw lobster roe, supplied chilled by a fishmonger','Omit for the plain sauce; roe is a flavoring, not a substitute for the sauce’s egg yolks.'),water(75,'roewater')]
ROE=['Put {{roe}} and {{roewater}} in a small saucepan. Bring to a gentle simmer and stir for about 3–5 minutes until the roe is bright red, firm and opaque throughout. Drain, cool promptly, then pound and press through a fine sieve. Keep refrigerated until needed.']

MI=[eggs(2),water(1000),yolks(4),oil(60),salt(.5),pepper(1),I('mustard',1,'tsp','prepared Dijon mustard','Use the same amount of another smooth prepared mustard.'),vinegar(30)]
MS=boil()+['Separate the firm cooked yolks and press them through a fine sieve into a cold bowl. Refrigerate the cooked whites separately for another dish and use within 2 days.',
 'Set the bowl over a larger bowl of ice water, keeping water out of the sauce. Whisk {{yolks}} into the sieved cooked yolks until smooth. Measure {{oil}} and whisk it in a few drops at a time, waiting for each addition to blend in.',
 'Once all the oil is incorporated, stir in {{salt}}, {{pepper}} and {{mustard}}. Whisk in {{vinegar}} gradually. The finished sauce should be creamy and spoonable.',
 'If the sauce begins to separate, stop mixing, cover and refrigerate for 40–60 minutes, then whisk again. This is the source’s cold-rest method and is not guaranteed to rescue a fully broken sauce. Keep the sauce cold throughout.',DAY]
r=add(134,'White House Cooked-and-Raw-Yolk Mayonnaise',14,35,'Cooked yolks and pasteurized raw yolks make a rich, peppery mayonnaise with a modest amount of oil, mustard and vinegar.',MI,MS,
 'The full source says four raw yolks with two hard-boiled ones; this adaptation interprets the latter as cooked yolks in that grammatical context, rather than adding egg whites. One tablespoon oil per raw yolk gives 60 ml oil. The original two heaping teaspoons salt would make this small batch very salty: the modern adaptation deliberately reduces it to half a level teaspoon, not an asserted conversion of the old heap. One teaspoon pepper, one teaspoon prepared mustard and 30 ml vinegar are retained. Fourteen small sauce portions and thirty-five-minute preparation are estimates; the optional cold-rest rescue adds 40–60 minutes. The full text’s lobster-coral addition for lobster salad is retained as a complete variation.');eggsource(r)
variant(r,'lobster-coral','With cooked lobster coral',copy.deepcopy(MI)+roeitems(),ROE+MS[:-1]+['Stir the sieved cooked lobster roe into the finished mayonnaise just before serving.']+[DAY]);r['source']+=FISHREF

FI=[I('fish',600,'g','raw skinless boneless cod fillets','Use the same raw weight of halibut or another lean white fish.'),water(1200,'fishwater'),I('fishsalt',.5,'tsp','fine salt for poaching','Reduce or omit; the liquid is discarded.'),eggs(4),water(1200),oil(60),salt(.5),pepper(.25),mustard(1),I('sugar',2,'tsp','white sugar','Use the same volume of fine caster sugar.'),vinegar(90),I('white',30,'g','commercially pasteurized egg white suitable for whipping, about one large white','Use a pasteurized shell-egg white of the same weight; do not use unpasteurized raw white.'),I('lettuce',100,'g','pale inner lettuce leaves, washed and dried','Use the same weight of tender butter-lettuce leaves.')]
POACH=['Bring {{fishwater}} and {{fishsalt}} to a simmer in a pan just large enough for {{fish}}. Lower in the fillets, adding hot drinking water only if needed to cover. Poach gently without a rolling boil for about 8–12 minutes, until the thickest part reaches 63°C (145°F), is opaque and separates easily. Thickness determines the cooking time.',
 'Lift the cooked fish into a shallow container, drain well and check for pin bones. Cool briefly over ice water, cover and refrigerate promptly at 4°C (40°F) or colder until fully cold, about 1 hour. Cut the cold fish into pieces about 2.5 cm long; do not mince it.']
FS=POACH+boil()+['Separate the firm cooked yolks and mash them to a smooth paste. Refrigerate the hard-boiled whites separately for another dish and use within 2 days.',
 'Gradually beat {{oil}} into the cooked-yolk paste. Mix in {{salt}}, {{pepper}}, {{mustard}} and {{sugar}}, then gradually beat in {{vinegar}} until the dressing is smooth and light.',
 'Immediately before assembly, whisk {{white}} in a clean bowl until frothy and softly foamy, rather than dry and stiff. Fold the froth gently into the cooked-yolk dressing.',
 'Put the cold fish in a serving bowl and fold in half of the finished dressing. Spread the remaining dressing over the top. Arrange {{lettuce}} around the edge and serve cold.',DAY]
r=add(137,'Cold Fish with Frothy Cooked-Yolk Dressing',4,100,'Cold white fish is coated with a tangy cooked-yolk dressing lightened with pasteurized egg-white froth and served with tender lettuce.',FI,FS,
 'The complete White House and Harland texts have the same pound of cooked fish, four cooked yolks, two teaspoons sugar, six tablespoons vinegar, egg-white froth and half-inside/half-on-top dressing method. The White House text additionally allows butter instead of salad oil; this is retained in full. A 600 g raw fillet starting weight aims for roughly the source’s pound of cooked fish but is an estimated cooking yield, not a weight conversion. The cooked-fish variation uses a measured 454 g directly. Oil, seasonings, lettuce weight, poaching liquid, four servings and timing are working choices. Harland’s blanched lettuce is interpreted here as pale inner leaves, consistent with the White House text’s explicit leaves from the heart; it is not an instruction to boil lettuce. Commercially pasteurized white replaces unspecified raw white.');fishdone(r)
vi=copy.deepcopy(FI)
for i in vi:
 if i['key']=='oil':i.update(key='butter',amount=60,unit='g',name='unsalted butter, softened but not melted',substitution='Use the oil-based recipe instead; the two amounts are modern working choices, not equal-volume conversions.')
variant(r,'butter-dressing','With the source’s butter dressing',vi,[s.replace('Gradually beat {{oil}}','Gradually beat {{butter}}') for s in FS])
vi=[i for i in copy.deepcopy(FI) if i['key'] not in ['fishwater','fishsalt']]
for i in vi:
 if i['key']=='fish':i.update(amount=454,name='cooked, chilled, skinless and boneless white fish',substitution='Use the freshly poached base recipe instead.')
variant(r,'cooked-fish','Starting with cold cooked fish',vi,['Use {{fish}} that was cooked through and promptly refrigerated at 4°C (40°F) or colder. Check carefully for bones, drain and cut into pieces about 2.5 cm long; keep cold while preparing the dressing.']+FS[2:])
merge(133,r,'Full Harland formula and method match the oil version of White House fish mayonnaise. The canonical recipe preserves the pale-inner-lettuce interpretation and the White House butter alternative in full, with both source credits and saved IDs.')
merge(138,r,'Truncated repeat of the same White House Mayonnaise Fish passage. The full canonical recipe restores the missing fish quantity, egg-white froth, lettuce border and complete dressing method.')

farmer=copy.deepcopy(records[rows[135]['id']]['recipe']);HALF=copy.deepcopy(farmer['ingredients'])
for i in HALF:i['amount']/=2
FM=farmer['steps'][:-1]
MK=[I('mackerel',1000,'g','two medium whole mackerel, cleaned and gutted, about 500 g each','Use the same cleaned weight of another similarly sized oily fish; adjust cooking to thickness.'),water(80,'bakewater'),I('cidervinegar',80,'ml','cider vinegar for baking','Use the same volume of white wine vinegar.'),I('tarragonvinegar',80,'ml','tarragon vinegar for baking','Use the same volume of white wine vinegar for a different flavor.'),I('cloves',12,'','whole cloves','Reduce or omit for a less strongly spiced fish.'),I('peppercorns',1,'tsp','whole black peppercorns','Use the same amount of white peppercorns.'),I('bakesalt',1,'tsp','fine salt for baking','Reduce or omit; the cooking liquid is discarded.'),I('bay',.25,'','dried bay leaf','Omit if preferred.'),I('paperbutter',5,'g','butter for the baking-paper cover','Use the same weight of neutral oil.'),I('gelatin',2,'g','unflavored powdered gelatin, approximately 200 Bloom','Use the manufacturer’s equivalent setting amount of leaf gelatin, soaking and draining it first.'),water(30,'gelwater'),I('plainreserve',60,'ml','plain mayonnaise reserved from the batch below; not an additional purchase','Reserve before adding gelatin.'),I('cucumber',150,'g','fresh cucumber','Use the same weight of peeled cucumber if its skin is tough.'),I('basketlemons',2,'','medium lemons for serving baskets','Use two small food-safe ramekins instead if the lemons are too small to hollow safely.'),I('choppedparsley',1,'tsp','finely chopped fresh parsley','Use the same volume of finely chopped chives.'),I('parsleysprigs',5,'g','fresh parsley sprigs','Use the same weight of fresh dill sprigs.')]+HALF
MKS=['Heat the oven to 180°C (350°F). Put {{mackerel}} in a snug baking dish with {{bakewater}}, {{cidervinegar}}, {{tarragonvinegar}}, {{cloves}}, {{peppercorns}}, {{bakesalt}} and {{bay}}. Brush a sheet of baking paper with {{paperbutter}} and lay it buttered-side down over the fish.',
 'Bake for about 20–30 minutes, until the thickest flesh reaches 63°C (145°F), is opaque and separates readily. Lift the fish out and discard the paper, spices and cooking liquid. When just safe to handle, remove the skin, backbone and pin bones carefully, keeping the fillets as intact as possible.',
 'Arrange the fillets in a shallow dish to resemble the two fish, cool briefly over ice water, then cover and refrigerate promptly until cold, about 1 hour. Prepare the mayonnaise while they chill.']+FM+['Measure {{plainreserve}} from the plain mayonnaise, cover and keep refrigerated for the lemon baskets. Keep the remaining mayonnaise in the mixing bowl.',
 'Sprinkle {{gelatin}} over {{gelwater}} in a small heatproof bowl and leave for 5 minutes. Set the bowl over hot water and stir until dissolved; do not boil. Cool until barely lukewarm and still fluid. Whisk a spoonful of the remaining mayonnaise into the gelatin, then whisk this mixture gradually back into the remaining mayonnaise.',
 'Spread the gelatin-thickened mayonnaise over the cold fish. Cover without touching the coating and refrigerate for about 1 hour until set and thoroughly cold.',
 'Wash {{basketlemons}}. For each basket, trim only a very thin slice from the base so it stands upright. Mark a band about 1 cm wide across the top; carefully cut away the upper quarter on each side, leaving the band attached as a handle. Scoop pulp from the lower half with a small spoon without piercing the skin or handle. Keep the pulp for another use. If the handle breaks, the hollowed lower half still works as a serving cup.',
 'Fill the lemon baskets with the reserved plain mayonnaise and sprinkle with {{choppedparsley}}. Thinly slice washed {{cucumber}} and arrange around the fish with the filled baskets and washed {{parsleysprigs}}. Serve cold.',DAY]
r=add(139,'Chilled Mackerel with Set Mayonnaise and Lemon Baskets',4,180,'Mackerel baked with two vinegars and whole spices is chilled under a lightly set mayonnaise coating, with cucumber and lemon baskets of plain mayonnaise.',MK,MKS,
 'The full Farmer recipe specifies two medium mackerel, one-third cup each water, cider vinegar and tarragon vinegar, twelve cloves, one teaspoon each peppercorns and salt, and a bit of bay. Modern measures give 80 ml of each liquid; the fish weight, quarter bay leaf, paper butter, baking temperature, thermometer endpoint and timing are supplied. Half the complete Dressing I makes the sauce; 60 ml is reserved plain before adding a chosen 2 g gelatin dissolved in 30 ml water to the remainder. Plain mayonnaise in the lemon baskets is distinct from the set coating. Cucumber, lemons and two parsley garnishes are measured working choices. Deboning, prompt shallow cooling, four servings and the three-hour total are modern instructions.');fishdone(r)

# Half of a full Dressing I batch goes into ravigote; the other half supplies the plain coating.
SI=[I('salmon',340,'g','canned salmon, drained weight, roughly one large can depending on brand','Use the same drained weight of canned pink or red salmon; use the label’s drained weight rather than assuming all cans match.'),I('lettuce',100,'g','tender lettuce leaves, washed and dried','Use the same weight of butter lettuce.'),I('spinach',60,'g','fresh spinach leaves','Use the same raw weight of young chard leaves without tough stems.'),water(500,'spinachwater'),I('spinachreserve',30,'ml','cooked squeezed spinach reserved from below, about two level tablespoons; not an additional purchase','Measure after cooking and squeezing; save any extra separately.'),I('capers',1,'tbsp','capers, drained','Use the same volume of finely chopped cornichons.'),I('shallot',15,'g','peeled shallot, about half a medium shallot','Use the same weight of mild onion.'),I('anchovies',12,'g','anchovy fillets, drained, about three fillets','Use the same weight of finely chopped smoked sprat for a different flavor.'),I('herbparsley',80,'ml','fresh parsley leaves, loosely packed before chopping','Use the same loose volume of chervil.'),I('watercress',120,'ml','cultivated watercress leaves, loosely packed','Use the same loose volume of baby spinach for a milder flavor.'),I('pimiento',30,'g','canned pimiento, drained','Use the same drained weight of roasted red pepper.'),I('truffle',5,'g','preserved ready-to-eat black truffle, drained','Use the same weight of a cooked mushroom cap, thinly sliced; this is a different garnish.')]+copy.deepcopy(farmer['ingredients'])
SS=['Briefly rinse {{salmon}} under cold drinking water in a sieve, drain thoroughly and pat dry. Remove any skin or hard bone fragments and separate into flakes. Cover and keep refrigerated.',
 'Bring {{spinachwater}} to a boil, add washed {{spinach}} and cook for about 1–2 minutes until wilted. Drain, cool promptly under cold running drinking water, then squeeze dry. Measure {{spinachreserve}} for the sauce and refrigerate any surplus separately for use within 2 days.']+FM+['Divide the finished plain mayonnaise into two equal portions. Keep one covered and chilled for the outer coating; use the other for the herb sauce.',
 'Wash and dry {{herbparsley}} and {{watercress}}. Finely chop {{shallot}} and {{anchovies}}. Pound these with {{capers}}, the reserved cooked spinach and the fresh greens in a mortar until finely broken down, then press through a fine sieve. Stir all the smooth strained herb mixture into one of the two equal mayonnaise portions.',
 'Arrange {{lettuce}} on a chilled platter. Gently moisten the salmon with the herb mayonnaise and mound it on the lettuce. Spread the reserved plain mayonnaise over the top. If a lighter coating is preferred, keep the unused portion covered in the refrigerator for another use within 3 days.',
 'Cut {{pimiento}} into small triangles and {{truffle}} into thin decorative slices or shapes. Arrange over the mayonnaise-coated salmon and serve cold.',DAY]
r=add(142,'Salmon with Ravigote Herb Mayonnaise',4,45,'Flaked salmon is dressed with spinach, watercress, parsley, caper and anchovy mayonnaise, then coated with plain mayonnaise and decorated with pimiento and truffle.',SI,SS,
 'The complete Farmer salmon recipe calls one unspecified can, a lettuce bed, ravigote mayonnaise, a separate plain mayonnaise coating, pimiento and truffle garnishes. The adaptation chooses 340 g drained salmon and measured garnishes. The herb sauce retains two tablespoons cooked spinach, one tablespoon capers, half a shallot, three anchovies, one-third cup parsley and half a cup watercress. The latter greens are measured as loose volumes of 80 ml and 120 ml, not falsely converted to grams. Fresh spinach and a complete cooking step supply the measured cooked portion. The printed herb sauce uses half the full Dressing I formula; this recipe makes a full batch, divides it equally, and uses the other half for the plain coating, accounting for any optional surplus. Four servings and forty-five minutes are estimates.');fishdone(r)

assert len(newids)==4 and len(merges)==2
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
(root/'recipe-aliases.json').write_text(json.dumps(list(aliases.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full fish and mayonnaise components with measured source variations and source-preserving consolidation','repair-batch-044.py'))
for s in merges:db.execute('insert or replace into decisions values(?,?,?,?,?)',(s['id'],s['bodySha256'],'prepared-duplicate','Full original comparison; equivalent fish dressing with all meaningful source options retained','repair-batch-044.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newAliases=len(merges),totalOverrides=len(records),totalAliases=len(aliases))))

